/**
 * API Keys Router — handles API key CRUD, rate limits, and usage stats
 */
import { router } from "../_core/trpc";
import { governedProtectedProcedure, fullyGovernedMutationProcedure } from "../governance/trpc-enforcement";
import { z } from "zod";
import { TRPCError } from "@trpc/server";
import * as db from "../supabase-adapter";

const protectedProcedure = governedProtectedProcedure;
// Security-sensitive mutations use full governance + structural integrity enforcement
const highStakesProcedure = fullyGovernedMutationProcedure;

export const apiKeysRouter = router({
  list: protectedProcedure.query(async ({ ctx }) => {
    return db.getApiKeysByUserId(ctx.user!.id);
  }),

  create: highStakesProcedure
    .input(z.object({
      name: z.string().min(1).max(100).optional(),
    }))
    .mutation(async ({ ctx, input }) => {
      // Per-plan API-key cap REMOVED (2026-07-06, owner request). It was blocking
      // key creation, and — because the subscriptions read is currently drifted
      // (getSubscriptionByUserId returns null → every user resolves to "free") —
      // it was capping ALL users at 1 key, not just free ones. Re-introduce
      // plan-based limits (free/pro/team/enterprise) once the billing/subscription
      // camelCase drift in supabase-db.ts is fixed and plans resolve correctly.
      return await db.createApiKey(ctx.user!.id, input.name);
    }),

  regenerate: highStakesProcedure
    .input(z.object({ keyId: z.number() }))
    .mutation(async ({ ctx, input }) => {
      return db.regenerateApiKey(ctx.user!.id, input.keyId);
    }),

  delete: protectedProcedure
    .input(z.object({ keyId: z.number() }))
    .mutation(async ({ ctx, input }) => {
      return db.deleteApiKey(ctx.user!.id, input.keyId);
    }),

  keyUsage: protectedProcedure
    .input(z.object({
      keyPrefix: z.string(),
      days: z.number().min(1).max(90).default(30),
    }))
    .query(async ({ ctx, input }) => {
      const keys = await db.getApiKeysByUserId(ctx.user!.id);
      const key = keys.find((k: any) => k.keyPrefix === input.keyPrefix);
      if (!key) {
        throw new TRPCError({ code: 'NOT_FOUND', message: 'API key not found' });
      }
      return db.getUsageByApiKeyPrefix(input.keyPrefix, input.days);
    }),

  updateRateLimit: protectedProcedure
    .input(z.object({
      keyId: z.number(),
      rateLimitOverride: z.number().nullable(),
    }))
    .mutation(async ({ ctx, input }) => {
      const keys = await db.getApiKeysByUserId(ctx.user!.id);
      const key = keys.find((k: any) => k.id === input.keyId);
      if (!key) {
        throw new TRPCError({ code: 'NOT_FOUND', message: 'API key not found' });
      }

      const subscription = await db.getSubscriptionByUserId(ctx.user!.id);
      const plan = subscription?.plan || 'free';
      if (plan === 'free' && input.rateLimitOverride !== null) {
        throw new TRPCError({
          code: 'FORBIDDEN',
          message: 'Custom rate limits require a paid plan. Upgrade to configure per-key limits.',
        });
      }

      if (input.rateLimitOverride !== null && input.rateLimitOverride !== -1) {
        if (input.rateLimitOverride < 1 || input.rateLimitOverride > 10000) {
          throw new TRPCError({
            code: 'BAD_REQUEST',
            message: 'Rate limit must be between 1 and 10,000 requests per minute, or -1 for unlimited.',
          });
        }
      }

      await db.updateApiKeyRateLimit(ctx.user!.id, input.keyId, input.rateLimitOverride);
      return { success: true };
    }),

  rateLimitTiers: protectedProcedure.query(async ({ ctx }) => {
    const subscription = await db.getSubscriptionByUserId(ctx.user!.id);
    const plan = subscription?.plan || 'free';
    const planDefaults: Record<string, number> = {
      free: 10,
      builder: 60,
      startup: 200,
      scale: 500,
      business: 1000,
      enterprise: 5000,
      enterprise_plus: 10000,
    };
    return {
      plan,
      defaultLimit: planDefaults[plan] || 10,
      canCustomize: plan !== 'free',
      maxAllowed: plan === 'enterprise_plus' ? 10000 : planDefaults[plan] ? planDefaults[plan] * 2 : 20,
    };
  }),
});

